// Score each L6M new SKU against Wayfair New SKU Playbook recipe thresholds.
// Green / Red / Unknown. Unknown does not inflate red count but is called out
// in the action plan so the SRM still has a supplier ask.

const cfg = $('Configure Inputs').first().json;
let rows = [];
try {
  rows = $('Pull New SKU Ramp Metrics').all().map((item) => item.json);
} catch (e) {
  rows = $input.all().map((item) => item.json);
}

rows = rows.filter((row) => row && row.sku);

function num(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function boolish(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'boolean') return value;
  const s = String(value).toLowerCase();
  if (['true', '1', 'y', 'yes'].includes(s)) return true;
  if (['false', '0', 'n', 'no'].includes(s)) return false;
  return null;
}

function status(pass) {
  if (pass === null) return 'UNKNOWN';
  return pass ? 'GREEN' : 'RED';
}

function scoreSku(row) {
  const wsi = num(row.wsi_l28);
  const avail = num(row.availability_l30);
  const visits = num(row.visits_l30) ?? 0;
  const cvr = num(row.cvr_l30);
  const classCvr = num(row.class_cvr_l30);
  const classVisitsP25 = num(row.class_visits_p25);
  const reviewCount = num(row.review_count);
  const inReviewProgram = boolish(row.in_review_program);
  const isAdvertised = boolish(row.is_advertised);
  const adSpend = num(row.ad_spend_l30);
  const adRoas = num(row.ad_roas_l30);
  const optimized = boolish(row.optimized_l28);
  const inPromo = boolish(row.in_upcoming_promo);

  const competitivePass = wsi === null ? null : wsi >= 0.85;
  const availablePass = avail === null ? null : avail >= 0.85;
  const visitsPass =
    classVisitsP25 === null ? (visits >= 50 ? true : visits > 0 ? false : null) : visits >= Math.max(50, classVisitsP25 * 0.5) || visits >= classVisitsP25;
  // Softer visit bar for brand-new SKUs: green if >= class P25 OR >= 50
  const visitsGreen =
    classVisitsP25 === null
      ? visits >= 50
        ? true
        : null
      : visits >= classVisitsP25 || visits >= 50;
  const cvrPass =
    cvr === null || classCvr === null
      ? null
      : cvr >= classCvr * 0.8;
  const reviewsPass = (reviewCount === null ? 0 : reviewCount) >= 5;
  // Review acceleration enrollment paused for v1.1 — do not gate or ask.
  const reviewProgramPass = null;
  // No ads row => treat as not advertising (RED), spend 0
  const adsLivePass = isAdvertised === null ? false : isAdvertised;
  const adSpendPass = adSpend === null ? (isAdvertised === null ? false : null) : adSpend >= 50;
  // ROAS is diagnostic only for new SKUs — never red/green gate
  const optimizedPass = optimized; // null until campaign-edit SoT exists
  const promoPass = inPromo;

  const metrics = {
    competitive_status: status(competitivePass),
    available_status: status(availablePass),
    visits_status: status(visitsGreen === false ? false : visitsGreen === true ? true : null),
    conversion_status: status(cvrPass),
    reviews_status: status(reviewsPass),
    review_program_status: 'PAUSED',
    ads_live_status: status(adsLivePass),
    ad_spend_status: status(adSpendPass),
    roas_status: 'DIAGNOSTIC',
    optimized_status: status(optimizedPass),
    promo_status: status(promoPass),
  };

  const actions = [];
  if (metrics.competitive_status === 'RED') {
    actions.push('Fix competitiveness / WSC so WSI is at or above 85%');
  }
  if (metrics.available_status === 'RED') {
    actions.push('Raise L30 availability above 85% (replenish, Castlegate, or inventory feed)');
  }
  if (metrics.visits_status === 'RED') {
    actions.push('Launch or scale a dedicated New SKU WSP/WSD campaign to unlock traffic');
  }
  if (metrics.conversion_status === 'RED') {
    actions.push('Diagnose CVR gap vs class (price, merch/imagery, reviews)');
  }
  if (metrics.reviews_status === 'RED') {
    actions.push('Get to 5+ reviews (RfS / RfR / Bazaarvoice — enrollment tracking paused)');
  }
  // Review acceleration enrollment paused — no action ask in v1.1
  if (metrics.ads_live_status === 'RED') {
    actions.push('Launch a dedicated New SKU WSP/WSD campaign (do not wait on reviews)');
  }
  if (metrics.ad_spend_status === 'RED') {
    actions.push('Fund at least $50 per SKU per month and avoid midday daily caps');
  }
  if (metrics.optimized_status === 'RED') {
    actions.push('Refresh New SKU campaign structure / bids on a 4-week cadence');
  }
  if (metrics.promo_status === 'RED' || metrics.promo_status === 'UNKNOWN') {
    actions.push('Submit SKU into the next loyalty / primary promo before the deadline');
  }

  // Deduplicate while preserving order; keep top 3 for summary
  const seen = new Set();
  const uniqueActions = [];
  for (const a of actions) {
    if (!seen.has(a)) {
      seen.add(a);
      uniqueActions.push(a);
    }
  }

  const gatedStatuses = [
    metrics.competitive_status,
    metrics.available_status,
    metrics.visits_status,
    metrics.conversion_status,
    metrics.reviews_status,
    // review_program_status paused — excluded from grade
    metrics.ads_live_status,
    metrics.ad_spend_status,
    // optimized UNKNOWN excluded from grade until SoT exists
    metrics.promo_status,
  ].filter((s) => s !== 'PAUSED');
  const redCount = gatedStatuses.filter((s) => s === 'RED').length;
  const greenCount = gatedStatuses.filter((s) => s === 'GREEN').length;
  const unknownCount = gatedStatuses.filter((s) => s === 'UNKNOWN').length;

  let overall;
  if (redCount === 0 && unknownCount === 0) overall = 'ON TRACK';
  else if (redCount === 0) overall = 'NEEDS DATA';
  else if (redCount <= 2) overall = 'NEEDS WORK';
  else overall = 'AT RISK';

  const summary =
    uniqueActions.length === 0
      ? 'Recipe looks healthy — keep monitoring and optimize every 4 weeks.'
      : `${row.sku} needs: ${uniqueActions
          .slice(0, 3)
          .map((a, i) => `(${i + 1}) ${a}`)
          .join('; ')}.`;

  return {
    ...row,
    ...metrics,
    red_count: redCount,
    green_count: greenCount,
    unknown_count: unknownCount,
    overall_grade: overall,
    top_actions: uniqueActions.slice(0, 3).join(' | '),
    action_summary: summary,
    ad_roas_l30: adRoas,
  };
}

const scored = rows.map(scoreSku).sort((a, b) => {
  if (b.red_count !== a.red_count) return b.red_count - a.red_count;
  return (Number(b.visits_l30) || 0) - (Number(a.visits_l30) || 0);
});

const supplierRollup = {};
for (const row of scored) {
  const key = row.supplier_id || row.supplier_name || 'unknown';
  if (!supplierRollup[key]) {
    supplierRollup[key] = {
      supplier_id: row.supplier_id,
      supplier_name: row.supplier_name,
      sku_count: 0,
      red_skus: 0,
      not_advertised: 0,
      low_reviews: 0,
      low_availability: 0,
    };
  }
  const s = supplierRollup[key];
  s.sku_count += 1;
  if (row.red_count > 0) s.red_skus += 1;
  if (row.ads_live_status !== 'GREEN') s.not_advertised += 1;
  if (row.reviews_status !== 'GREEN') s.low_reviews += 1;
  if (row.available_status === 'RED') s.low_availability += 1;
}

const portfolio = Object.values(supplierRollup).sort((a, b) => b.red_skus - a.red_skus);
const total = scored.length || 1;
const gapStats = {
  pct_not_advertised: scored.filter((r) => r.ads_live_status !== 'GREEN').length / total,
  pct_under_5_reviews: scored.filter((r) => r.reviews_status !== 'GREEN').length / total,
  pct_low_availability: scored.filter((r) => r.available_status === 'RED').length / total,
  pct_at_risk: scored.filter((r) => r.overall_grade === 'AT RISK').length / total,
};

const legend = [
  { metric: 'Competitive (WSI L28)', green_rule: 'WSI ≥ 0.85', red_rule: 'WSI < 0.85', default_ask: 'Fix WSC / competitiveness' },
  { metric: 'Available (L30)', green_rule: 'Availability ≥ 85%', red_rule: 'Availability < 85%', default_ask: 'Replenish / Castlegate / inventory feed' },
  { metric: 'Visits (L30)', green_rule: '≥ class P25 or ≥ 50 visits', red_rule: 'Below both bars', default_ask: 'Start / scale New SKU ads' },
  { metric: 'Conversion (L30)', green_rule: 'Within 20% of class avg CVR', red_rule: 'Below class −20%', default_ask: 'Reviews + merch + price check' },
  { metric: 'Review count', green_rule: '≥ 5 reviews', red_rule: '< 5 reviews', default_ask: 'Enroll RfS / RfR / Bazaarvoice' },
  { metric: 'Review program', green_rule: 'Paused in v1.1', red_rule: 'Paused in v1.1', default_ask: 'Re-enable later — Partner Home Review Acceleration' },
  { metric: 'Advertising live', green_rule: 'WSP and/or WSD live', red_rule: 'No active campaign', default_ask: 'Launch dedicated New SKU campaign' },
  { metric: 'Ad spend level', green_rule: '≥ $50 / SKU / month', red_rule: 'Below $50 / month', default_ask: 'Raise budget / remove daily caps' },
  { metric: 'ROAS', green_rule: 'Diagnostic only for new SKUs', red_rule: 'Never used as early fail', default_ask: 'Use for graduation decisions' },
  { metric: 'Optimizations', green_rule: 'Refreshed ≤ 28 days', red_rule: 'Stale / never optimized', default_ask: '4-week campaign refresh' },
  { metric: 'Upcoming promos', green_rule: 'In next loyalty / primary', red_rule: 'Not submitted', default_ask: 'Submit before deadline' },
];

const srm = cfg.srm_contact_name || scored[0]?.srm_contact_name || 'SRM';
const lookback = cfg.lookback_months || 6;
const spreadsheetTitle = `New SKU Ramp Report Card — ${srm} — L${lookback}M — ${new Date().toISOString().slice(0, 10)}`;

function pct(v) {
  return `${(Number(v) * 100).toFixed(0)}%`;
}

const emailHtml = `
<div style="font-family:Arial,sans-serif;color:#0f2744;line-height:1.45">
  <h2 style="margin:0 0 8px 0;">New SKU Ramp Report Card</h2>
  <p style="margin:0 0 12px 0;color:#475569;">SRM: <strong>${srm}</strong> · Window: L${lookback}M launches · SKUs: <strong>${scored.length}</strong> · Suppliers: <strong>${portfolio.length}</strong></p>
  <!-- SPREADSHEET_LINK -->
  <p style="margin:0 0 8px 0;"><strong>Portfolio recipe gaps</strong></p>
  <ul style="margin:0 0 16px 18px;padding:0;color:#334155;">
    <li>${pct(gapStats.pct_not_advertised)} not confirmed advertising</li>
    <li>${pct(gapStats.pct_under_5_reviews)} under 5 reviews / review status unknown</li>
    <li>${pct(gapStats.pct_low_availability)} below 85% availability</li>
    <li>${pct(gapStats.pct_at_risk)} graded AT RISK</li>
  </ul>
  <p style="margin:0;color:#64748b;font-size:12px;">Tabs: SKU Report Cards, Summary Action Plan, Threshold Legend. Review acceleration enrollment is paused in v1.1. Ads + review count + upcoming promo are wired from BigQuery.</p>
</div>`;

return [{
  json: {
    srm_contact_name: srm,
    lookback_months: lookback,
    spreadsheetTitle,
    subject: `New SKU Ramp Report Card — ${srm} (L${lookback}M)`,
    emailHtml,
    gap_stats: gapStats,
    supplier_rollup: portfolio,
    sku_cards: scored,
    summary_rows: scored.map((row) => ({
      supplier_name: row.supplier_name,
      supplier_id: row.supplier_id,
      sku: row.sku,
      sku_name: row.sku_name,
      launch_date: row.launch_date,
      days_since_launch: row.days_since_launch,
      overall_grade: row.overall_grade,
      red_count: row.red_count,
      visits_l30: row.visits_l30,
      action_summary: row.action_summary,
      top_actions: row.top_actions,
    })),
    legend,
  },
}];

const analysis = $('Score Report Cards').first().json;
const rows = analysis.sku_cards || [];
if (!rows.length) {
  return [{
    json: {
      SRM: analysis.srm_contact_name || '',
      'Supplier ID': '',
      'Supplier Name': '(No L6M new SKUs found for this SRM)',
      SKU: '',
      'SKU Name': '',
      Class: '',
      'Launch Date': '',
      'Days Since Launch': '',
      'Overall Grade': '',
      Reds: '',
      'WSI L28': '',
      'Competitive': '',
      'Availability L30': '',
      Available: '',
      'Visits L30': '',
      Visits: '',
      'CVR L30': '',
      'Class CVR L30': '',
      Conversion: '',
      'Review Count': '',
      Reviews: '',
      'Review Program': '',
      'Ads Live': '',
      'Ad Spend L30': '',
      'Ad Spend': '',
      'ROAS L30': '',
      Optimized: '',
      'Upcoming Promo': '',
      'Action Summary': '',
    },
  }];
}

function pct(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return '';
  return `${(n * 100).toFixed(1)}%`;
}

function money(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return '';
  return Number(n.toFixed(2));
}

return rows.map((row) => ({
  json: {
    SRM: row.srm_contact_name || analysis.srm_contact_name || '',
    'Supplier ID': row.supplier_id ?? '',
    'Supplier Name': row.supplier_name || '',
    SKU: row.sku || '',
    'SKU Name': row.sku_name || '',
    Class: row.class_name || '',
    'Launch Date': row.launch_date || '',
    'Days Since Launch': row.days_since_launch ?? '',
    'Overall Grade': row.overall_grade || '',
    Reds: row.red_count ?? '',
    'WSI L28': row.wsi_l28 == null ? '' : Number(Number(row.wsi_l28).toFixed(3)),
    Competitive: row.competitive_status || '',
    'Availability L30': pct(row.availability_l30),
    Available: row.available_status || '',
    'Visits L30': row.visits_l30 ?? 0,
    Visits: row.visits_status || '',
    'CVR L30': pct(row.cvr_l30),
    'Class CVR L30': pct(row.class_cvr_l30),
    Conversion: row.conversion_status || '',
    'Review Count': row.review_count ?? '',
    Reviews: row.reviews_status || '',
    'Review Program': row.review_program_status || '',
    'Ads Live': row.ads_live_status || '',
    'Ad Spend L30': money(row.ad_spend_l30),
    'Ad Spend': row.ad_spend_status || '',
    'ROAS L30': row.ad_roas_l30 == null ? '' : Number(Number(row.ad_roas_l30).toFixed(2)),
    Optimized: row.optimized_status || '',
    'Upcoming Promo': row.promo_status || '',
    'Action Summary': row.action_summary || '',
  },
}));

const analysis = $('Score Report Cards').first().json;
const rows = analysis.summary_rows || [];
if (!rows.length) {
  return [{
    json: {
      'Supplier Name': '(No SKUs)',
      'Supplier ID': '',
      SKU: '',
      'SKU Name': '',
      'Launch Date': '',
      'Days Since Launch': '',
      'Overall Grade': '',
      Reds: '',
      'Visits L30': '',
      'What it needs to ramp': '',
    },
  }];
}
return rows.map((row) => ({
  json: {
    'Supplier Name': row.supplier_name || '',
    'Supplier ID': row.supplier_id ?? '',
    SKU: row.sku || '',
    'SKU Name': row.sku_name || '',
    'Launch Date': row.launch_date || '',
    'Days Since Launch': row.days_since_launch ?? '',
    'Overall Grade': row.overall_grade || '',
    Reds: row.red_count ?? '',
    'Visits L30': row.visits_l30 ?? 0,
    'What it needs to ramp': row.action_summary || '',
  },
}));

const analysis = $('Score Report Cards').first().json;
return (analysis.legend || []).map((row) => ({ json: {
  Metric: row.metric,
  Green: row.green_rule,
  Red: row.red_rule,
  'Default Ask': row.default_ask,
}}));

const analysis = $('Score Report Cards').first().json;
const sheet = $('Create Spreadsheet').first().json || {};
const spreadsheetId = sheet.spreadsheetId || sheet.id || null;
const spreadsheetUrl =
  sheet.spreadsheetUrl ||
  (spreadsheetId ? `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit` : '');

const linkHtml = spreadsheetUrl
  ? `<div style="margin:0 0 16px 0;padding:12px 14px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;font-family:Arial,sans-serif;font-size:13px;color:#1e3a8a;"><strong style="color:#0f2744;">Workbook:</strong> <a href="${spreadsheetUrl}" style="color:#1d4ed8;text-decoration:underline;">Open New SKU Ramp Report Card</a><div style="font-size:11px;color:#64748b;margin-top:4px;">Tabs: SKU Report Cards, Summary Action Plan, Threshold Legend.</div></div>`
  : '<div style="margin:0 0 16px 0;padding:12px 14px;background:#fff7ed;border:1px solid #fdba74;border-radius:8px;font-family:Arial,sans-serif;font-size:13px;color:#9a3412;"><strong>Workbook:</strong> spreadsheet URL unavailable.</div>';

return [{
  json: {
    ...analysis,
    spreadsheetId,
    spreadsheetUrl,
    emailHtml: String(analysis.emailHtml || '').replace('<!-- SPREADSHEET_LINK -->', linkHtml),
    subject: analysis.subject || 'New SKU Ramp Report Card',
  },
}];
